                                <circle cx="412.874" cy="229.381" r="0.8" fill="white" opacity="0.9" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                            </svg>
                         </div>
                     </div>
                 </div>

                 {/* GIFT BUBBLE */}
                 {isGiftReady && !isTextVisible && (
